import pandas as pd
from collections import defaultdict, deque

df = pd.read_csv('/app/dataset/hospital_compensation_registry.csv')

adj = defaultdict(list)
for index, row in df.iterrows():
    u = row['patient_id']
    v = row['emergency_contact_patient_id']
    if pd.notna(v):
        adj[u].append(v)
        adj[v].append(u)

nan_claims = set(df[df['compensation_reason'].isna()]['patient_id'])

def bfs(start):
    q = deque([(start, 0)])
    visited = {start}
    res = []
    while q:
        curr, dist = q.popleft()
        if curr in nan_claims:
            res.append((dist, curr))
        for nxt in adj[curr]:
            if nxt not in visited:
                visited.add(nxt)
                q.append((nxt, dist + 1))
    return sorted(res)[:5]

for claimant in ['PAT_265', 'PAT_033', 'PAT_006']:
    print(f"\nDistances from {claimant}:")
    print(bfs(claimant))

EOF
python3 explore.py

