import pandas as pd

df = pd.read_csv('/app/dataset/hospital_compensation_registry.csv')

def get_path(start, end):
    from collections import deque
    q = deque([[start]])
    visited = {start}
    while q:
        path = q.popleft()
        node = path[-1]
        if node == end:
            return path

        neighbors = set()
        ec = df[df['patient_id'] == node]['emergency_contact_patient_id'].values[0]
        if pd.notna(ec): neighbors.add(ec)
        for e in df[df['emergency_contact_patient_id'] == node]['patient_id'].tolist():
            neighbors.add(e)

        for n in neighbors:
            if n not in visited:
                visited.add(n)
                q.append(path + [n])
    return None

nan_claims = df[df['compensation_reason'].isna()]['patient_id'].tolist()
death_claims = ['PAT_265', 'PAT_033', 'PAT_006']

for d in death_claims:
    print(f"\nPaths from {d} to NaN claims (up to distance 3):")
    for n in nan_claims:
        path = get_path(d, n)
        if path and len(path) <= 4:
            print(f"{n}: {' -> '.join(path)}")

EOF
